script:
Get-Service -Name wuauserv, bits, cryptsvc | Select-Object Name, Status, StartType
Write-Host 'Checking CBS Log for missing package references...'
if (Test-Path 'C:\Windows\Logs\CBS\CBS.log') {
    Select-String -Path 'C:\Windows\Logs\CBS\CBS.log' -Pattern '0x800f0831' -Context 0,2 | Select-Object -First 5
}

$paths = @('C:\Windows\SoftwareDistribution', 'C:\Windows\System32\catroot2')
foreach ($path in $paths) {
    if (Test-Path $path) {
        $acl = Get-Acl -Path $path
        [PSCustomObject]@{ Path = $path; Owner = $acl.Owner; AccessToString = $acl.AccessToString.Substring(0, [Math]::Min(100, $acl.AccessToString.Length)) }
    }
}

Get-Service -Name "WinDefend", "SecurityHealthService", "wscsvc" | Select-Object Name, Status, StartType
Write-Host "Defender 보안 정의 초기화 수행 중..." -ForegroundColor Green
if (Test-Path "C:\Program Files\Windows Defender\MpCmdRun.exe") {
    Start-Process -FilePath "C:\Program Files\Windows Defender\MpCmdRun.exe" -ArgumentList "-RemoveDefinitions -All" -Wait -WindowStyle Hidden
    Start-Process -FilePath "C:\Program Files\Windows Defender\MpCmdRun.exe" -ArgumentList "-SignatureUpdate" -Wait -WindowStyle Hidden
}

Stop-Service -Name wuauserv, bits, WinDefend -Force -ErrorAction SilentlyContinue
$defPath = "C:\ProgramData\Microsoft\Windows Defender\Definition Updates"
if (Test-Path $defPath) {
    Get-ChildItem -Path $defPath -Recurse | Remove-Item -Force -Recurse -ErrorAction SilentlyContinue
}
Start-Service -Name bits, wuauserv, WinDefend -ErrorAction SilentlyContinue
if (Test-Path "C:\Program Files\Windows Defender\MpCmdRun.exe") {
    Start-Process -FilePath "C:\Program Files\Windows Defender\MpCmdRun.exe" -ArgumentList "-SignatureUpdate" -NoNewWindow
}

Write-Host "[Windows Licensing Diagnostic]" -ForegroundColor Cyan
Get-CimInstance -ClassName SoftwareLicensingProduct | Where-Object { $_.PartialProductKey } | Select-Object Name, LicenseStatus, PartialProductKey | Format-Table -AutoSize
$oemKey = (Get-CimInstance -ClassName SoftwareLicensingService).OA3xOriginalProductKey
if ($oemKey) {
    Write-Host "Detected OEM Firmware Key: $oemKey" -ForegroundColor Green
} else {
    Write-Host "No embedded OEM Firmware Key found in UEFI/BIOS." -ForegroundColor Yellow
}

Write-Host "Resetting Driver Verifier settings..." -ForegroundColor Cyan
verifier /reset
Get-PnpDevice -Class "System" | Where-Object {$_.Status -ne "OK"}

Get-Process -Name 'WinStore.App', 'StoreExperienceHost' -ErrorAction SilentlyContinue | Stop-Process -Force
Start-Process 'wsreset.exe' -Wait
Get-AppxPackage -AllUsers *WindowsStore* | Foreach {Add-AppxPackage -DisableDevelopmentMode -Register "$($_.InstallLocation)\AppXManifest.xml"}

Stop-Service -Name 'AppXSvc' -Force -ErrorAction SilentlyContinue
$cachePath = "$env:LOCALAPPDATA\Packages\Microsoft.WindowsStore_8wekyb3d8bbwe\LocalCache"
if (Test-Path $cachePath) { Remove-Item -Path "$cachePath\*" -Recurse -Force -ErrorAction SilentlyContinue }
Start-Service -Name 'AppXSvc' -ErrorAction SilentlyContinue
Get-AppxPackage -AllUsers *Microsoft.WindowsStore* | Foreach {Add-AppxPackage -DisableDevelopmentMode -Register "$($_.InstallLocation)\AppXManifest.xml"}

# PowerShell Repair Script for Defender Error 0x800704ec
$regPaths = @(
    'HKLM:\SOFTWARE\Policies\Microsoft\Windows Defender',
    'HKLM:\SOFTWARE\Policies\Microsoft\Windows Defender\Real-Time Protection'
)

foreach ($path in $regPaths) {
    if (Test-Path $path) {
        Remove-ItemProperty -Path $path -Name 'DisableAntiSpyware' -ErrorAction SilentlyContinue
        Remove-ItemProperty -Path $path -Name 'DisableRealtimeMonitoring' -ErrorAction SilentlyContinue
        Write-Host "Removed restriction policy from $path"
    }
}

Set-Service -Name 'WinDefend' -StartupType Automatic -ErrorAction SilentlyContinue
Start-Service -Name 'WinDefend' -ErrorAction SilentlyContinue
Update-MpSignature -ErrorAction SilentlyContinue
Get-Service -Name 'WinDefend' | Select-Object Name, Status, StartType

# PowerShell Repair Script for Security Service Error 0x80070424
$secServices = @('wscsvc', 'WinDefend', 'mpsvc', 'SecurityHealthService')

foreach ($serviceName in $secServices) {
    $svc = Get-Service -Name $serviceName -ErrorAction SilentlyContinue
    if ($svc) {
        Set-Service -Name $serviceName -StartupType Automatic -ErrorAction SilentlyContinue
        if ($svc.Status -ne 'Running') {
            Start-Service -Name $serviceName -ErrorAction SilentlyContinue
        }
        Write-Host "Service '$serviceName' status: $($svc.Status)"
    } else {
        Write-Warning "Service '$serviceName' is missing from registry."
    }
}

Write-Host "Running system integrity check..."
sfc /scannow
DISM.exe /Online /Cleanup-Image /RestoreHealth

# Windows Audio RPC Dependent Services Recovery Script
$audioServices = @('RpcSs', 'DcomLaunch', 'AudioEndpointBuilder', 'Audiosrv')

foreach ($svcName in $audioServices) {
    $svc = Get-Service -Name $svcName -ErrorAction SilentlyContinue
    if ($svc) {
        Set-Service -Name $svcName -StartupType Automatic
        if ($svc.Status -ne 'Running') {
            Start-Service -Name $svcName -ErrorAction SilentlyContinue
            Write-Host "Started service: $svcName" -ForegroundColor Green
        } else {
            Write-Host "Service $svcName is already running." -ForegroundColor Cyan
        }
    }
}

# Restart AudioEndpointBuilder and Audiosrv to re-establish RPC binding
Restart-Service -Name AudioEndpointBuilder -Force -ErrorAction SilentlyContinue
Restart-Service -Name Audiosrv -Force -ErrorAction SilentlyContinue
Write-Host 'Audio Services RPC bindings refreshed successfully.' -ForegroundColor Green

Write-Output '=== Diagnostics & Repair for Error 0x80072EE7 (DNS Name Resolution) ==='

# 1. Clear DNS Client Cache
Write-Output 'Flushing local DNS cache...'
Clear-DnsClientCache

# 2. Inspect Windows hosts file for interfering Microsoft/Update endpoints
$hostsPath = "$env:SystemRoot\System32\drivers\etc\hosts"
if (Test-Path $hostsPath) {
    $hostsContent = Get-Content -Path $hostsPath
    $blockedDomains = $hostsContent | Where-Object { $_ -match 'microsoft|windowsupdate|msftconnecttest' -and $_ -notmatch '^\s*#' }
    if ($blockedDomains) {
        Write-Warning "Potentially blocking entries found in hosts file:"
        $blockedDomains | ForEach-Object { Write-Warning " - $_" }
        Write-Output "Note: Please inspect C:\Windows\System32\drivers\etc\hosts to remove unauthorized overrides."
    } else {
        Write-Output 'Hosts file clean: No conflicting Microsoft update entries detected.'
    }
}

# 3. Renew IP configuration
Write-Output 'Renewing DHCP leases...'
ipconfig /renew | Out-Null

# 4. Test DNS resolution for core Windows Update endpoints
$testDomains = @('slscr.update.microsoft.com', 'fe3.delivery.mp.microsoft.com')
foreach ($domain in $testDomains) {
    try {
        $result = Resolve-DnsName -Name $domain -ErrorAction Stop
        Write-Output "[PASS] Successfully resolved: $domain (IP: $($result.IPAddress | Select-Object -First 1))"
    } catch {
        Write-Warning "[FAIL] Could not resolve: $domain. Consider configuring public DNS (e.g., 1.1.1.1 / 8.8.8.8)."
    }
}

Write-Output 'Diagnostic routine completed.'
